def plan(n,t,focus,work,year,desc,region,vocab,verbs,expr,sound,names,s1,s2):
    return {'n':n,'t':t,'focus':focus,'work':work,'year':year,'desc':desc,'region':region,
            'v':[(w,pt,pron) for w,pt,pron in vocab],'vb':verbs,
            'ex':sum(([a,b] for a,b in expr),[]),'sound':(sound,[x[0] for x in vocab[:3]]),
            's1':[[names[i%2],*line] for i,line in enumerate(s1)],
            's2':[[names[i%2],*line] for i,line in enumerate(s2)]}

