# Locate episodes and rebuild in order, preserving the existing metadata outside authored fields.
files={}
for path in (ROOT/'data').glob('es-a2_*.json'):
 data=json.loads(path.read_text(encoding='utf-8'))
 for e in data: files[e['n']]=(path,e)
prev=files[388][1]
for p in P:
 path,e=files[p['n']]
 new=base.make(e,p,prev)
 new['t']=p['t']; new['s']=f"{p['region']} · {p['focus']} · referencia: {p['work']} · {p['year']}"
 files[p['n']]=(path,new); prev=new
for path in sorted({p for p,e in files.values()}):
 data=json.loads(path.read_text(encoding='utf-8'))
 repl={n:e for n,(p,e) in files.items() if p==path and 389<=n<=398}
 if repl:
  for i,e in enumerate(data):
   if e['n'] in repl: data[i]=repl[e['n']]
  path.write_text(json.dumps(data,ensure_ascii=False,separators=(',',':')),encoding='utf-8')
print('wrote',len(P),'episodes')
